"""Shared equal-rise Bundle crown field for physically common cross-sections.

This extracts the established squared-shoulder law for new construction
callers. Existing Bundle builders retain their original graphs. A positive
gap is a plateau; an overlap is one normalized crown, never two summed crowns.
The caller must supply a common datum/rise and an actual straight physical
cross-section. Independent terminal profiles require their own adapter.
"""
import bpy
from .path_surface_nodes import _Nodes

NAME = 'Prochitecture Streets / Equal-rise Bundle crown field v1'


def build():
    if NAME in bpy.data.node_groups: return bpy.data.node_groups[NAME]
    tree = bpy.data.node_groups.new(NAME, 'GeometryNodeTree'); g = _Nodes(tree)
    for name, kind, default in (
            ('Coordinate', 'Float', 0.), ('Left Shoulder', 'Float', 4.),
            ('Right Start', 'Float', 6.), ('Span', 'Float', 10.),
            ('Datum', 'Float', 0.), ('Rise', 'Float', .08)):
        socket = tree.interface.new_socket(name=name, in_out='INPUT', socket_type='NodeSocket'+kind)
        socket.default_value = default
    for name, kind in (('Height', 'Float'), ('Normalized Height', 'Float'),
                       ('Plateau Width', 'Float'), ('Peak Coordinate', 'Float'), ('Valid', 'Bool')):
        tree.interface.new_socket(name=name, in_out='OUTPUT', socket_type='NodeSocket'+kind)
    inp = g.node('NodeGroupInput', 'Physical common fibre; equal rise and datum')
    out = g.node('NodeGroupOutput', 'One bounded crown or positive-gap plateau')
    q, a, b, span, datum, rise = [inp.outputs[k] for k in
        ('Coordinate', 'Left Shoulder', 'Right Start', 'Span', 'Datum', 'Rise')]
    right = g.math('SUBTRACT', span, b)
    left_penalty = g.math('DIVIDE', g.math('MAXIMUM', 0., g.math('SUBTRACT', a, q)), g.math('MAXIMUM', 1e-6, a))
    right_penalty = g.math('DIVIDE', g.math('MAXIMUM', 0., g.math('SUBTRACT', q, b)), g.math('MAXIMUM', 1e-6, right))
    a2, r2 = g.math('MULTIPLY', a, a), g.math('MULTIPLY', right, right)
    denominator = g.math('ADD', a2, r2)
    overlap = g.math('MAXIMUM', 0., g.math('SUBTRACT', a, b))
    peak = g.math('SUBTRACT', 1., g.math('DIVIDE', g.math('MULTIPLY', overlap, overlap),
        g.math('MAXIMUM', 1e-6, denominator)))
    penalty = g.math('ADD', g.math('MULTIPLY', left_penalty, left_penalty),
        g.math('MULTIPLY', right_penalty, right_penalty))
    normalized = g.math('MAXIMUM', 0., g.math('MINIMUM', 1.,
        g.math('DIVIDE', g.math('SUBTRACT', 1., penalty), g.math('MAXIMUM', .5, peak))))
    peak_q = g.math('DIVIDE', g.math('ADD', g.math('MULTIPLY', a, r2), g.math('MULTIPLY', b, a2)),
        g.math('MAXIMUM', 1e-6, denominator))
    peak_q = g.switch(g.compare(b, a, 'GREATER_EQUAL'), peak_q, g.math('MULTIPLY', .5, g.math('ADD', a, b)))
    valid = g.all(*(g.compare(v, 1e-5, 'GREATER_THAN') for v in (a, right, b, g.math('SUBTRACT', span, a))),
        g.compare(rise, 0., 'GREATER_EQUAL'), g.compare(q, -1e-5, 'GREATER_EQUAL'),
        g.compare(q, g.math('ADD', span, 1e-5), 'LESS_EQUAL'))
    for name, value in (
            ('Height', g.math('ADD', datum, g.math('MULTIPLY', rise, normalized))),
            ('Normalized Height', normalized), ('Plateau Width', g.math('MAXIMUM', 0., g.math('SUBTRACT', b, a))),
            ('Peak Coordinate', peak_q), ('Valid', valid)):
        g.set(value, out.inputs[name])
    return tree
